const recipients = await resolveRecipients(msg);   // config/registry-driven
const outcomes = await Promise.allSettled(
    recipients.map(r => deliver(r, structuredClone(msg))));   // a copy per recipient
outcomes.forEach((o, i) => {
    if (o.status === 'rejected') log.warn({ recipient: recipients[i], err: o.reason });
});
